//! GML runtime glue for code generated by tools/gml2c (zig_emitter.py).
//! Port of packaged_src/src/gml/gml_rt.h / gml_rt.c.
//!
//! GML expression semantics follow the GameMaker-HTML5 runner:
//!  - reals compare with an epsilon of 1e-5 (yyfequal / yyfless ...,
//!    Function_Maths.js L2073-2152); NaN comparisons are false;
//!  - truthiness is `value > 0.5` (yyGetBool, yyTypes.js L318);
//!  - `obj.var` reads/writes the instance yyInst() resolves to (see `deref`);
//!    unresolvable targets read 0 and ignore writes;
//!  - `div`, `mod`, bitwise and shift operators follow yyfdiv, yyfmod (JS %),
//!    yyfbitand/or/xor (ToInt32) and yyfbitshiftleft/right.
//!
//! Calling convention of generated code: every script and event receives the
//! current `self` and `other` instances, both non-null. Event wrappers bracket
//! their body with `eventPush` / `eventPop`, which also bracket the string
//! scratch and temporary arrays (agents/zig/WORKER.md section 5). Scripts do
//! not bracket: their temporaries belong to the calling event.
//!
//! Memory: no garbage collector. Strings returned here are views valid until
//! the current event returns; persistent stores go through the `*Set`
//! helpers, `StringManager.assign*` or array `Slot`s.

const std = @import("std");
const runtime = @import("runtime");

const math = runtime.math;
const value = runtime.value;
const string = runtime.string;
const instance = runtime.instance;
const room = runtime.room;
const loop = runtime.loop;

pub const Value = runtime.Value;
pub const Slot = value.Slot;
pub const Instance = runtime.Instance;
pub const EventFn = runtime.object.EventFn;
pub const StringManager = runtime.StringManager;
pub const ArrayManager = runtime.ArrayManager;

pub const GM_SELF = instance.GM_SELF;
pub const GM_OTHER = instance.GM_OTHER;
pub const GM_ALL = instance.GM_ALL;
pub const GM_NOONE = instance.GM_NOONE;

fn sm() *StringManager {
    return StringManager.get();
}

// ---------------------------------------------------------------------------
// Values
// ---------------------------------------------------------------------------

pub inline fn vreal(d: f32) Value {
    return Value.fromReal(d);
}

pub inline fn vundef() Value {
    return Value.UNDEFINED;
}

/// Boxes a string view (literal or scratch).
pub inline fn vs(s: []const u8) Value {
    return Value.fromString(s);
}

/// bool -> GML real (1 / 0).
pub inline fn b2r(b: bool) f32 {
    return if (b) 1.0 else 0.0;
}

/// yyGetReal
pub inline fn real(v: Value) f32 {
    return if (v == .real) v.real else v.toReal();
}

/// yyGetBool on a real.
pub inline fn truthy(d: f32) bool {
    return d > 0.5;
}

pub inline fn vtruthy(v: Value) bool {
    return v.toBool();
}

// ---------------------------------------------------------------------------
// Comparisons (yyfequal, yyfless, ...)
// ---------------------------------------------------------------------------

const CMP_UNORDERED = value.CMP_UNORDERED;

pub inline fn eq(a: f32, b: f32) bool {
    return value.compareReal(a, b) == 0;
}

pub inline fn ne(a: f32, b: f32) bool {
    return value.compareReal(a, b) != 0;
}

pub inline fn lt(a: f32, b: f32) bool {
    const r = value.compareReal(a, b);
    return r != CMP_UNORDERED and r < 0;
}

pub inline fn le(a: f32, b: f32) bool {
    const r = value.compareReal(a, b);
    return r != CMP_UNORDERED and r <= 0;
}

pub inline fn gt(a: f32, b: f32) bool {
    const r = value.compareReal(a, b);
    return r != CMP_UNORDERED and r > 0;
}

pub inline fn ge(a: f32, b: f32) bool {
    const r = value.compareReal(a, b);
    return r != CMP_UNORDERED and r >= 0;
}

pub inline fn veq(a: Value, b: Value) bool {
    return value.compare(a, b) == 0;
}

pub inline fn vne(a: Value, b: Value) bool {
    return value.compare(a, b) != 0;
}

pub inline fn vlt(a: Value, b: Value) bool {
    const r = value.compare(a, b);
    return r != CMP_UNORDERED and r < 0;
}

pub inline fn vle(a: Value, b: Value) bool {
    const r = value.compare(a, b);
    return r != CMP_UNORDERED and r <= 0;
}

pub inline fn vgt(a: Value, b: Value) bool {
    const r = value.compare(a, b);
    return r != CMP_UNORDERED and r > 0;
}

pub inline fn vge(a: Value, b: Value) bool {
    const r = value.compare(a, b);
    return r != CMP_UNORDERED and r >= 0;
}

/// switch/case match: same kind, reals within epsilon, strings equal.
pub fn case(subject: Value, label: Value) bool {
    if (std.meta.activeTag(subject) != std.meta.activeTag(label)) return false;
    return switch (subject) {
        .real => |r| value.compareReal(r, label.real) == 0,
        .string => |s| std.mem.eql(u8, s, label.string),
        .array_ref => |r| r == label.array_ref,
        .undefined => true,
    };
}

pub inline fn rcase(subject: f32, label: f32) bool {
    return value.compareReal(subject, label) == 0;
}

// ---------------------------------------------------------------------------
// Strings
// ---------------------------------------------------------------------------

/// yyCompareVal on two strings: byte order of the UTF-8 text.
pub fn strCmp(a: []const u8, b: []const u8) i32 {
    return switch (std.mem.order(u8, a, b)) {
        .lt => -1,
        .eq => 0,
        .gt => 1,
    };
}

pub inline fn strEq(a: []const u8, b: []const u8) bool {
    return std.mem.eql(u8, a, b);
}

pub inline fn strNe(a: []const u8, b: []const u8) bool {
    return !std.mem.eql(u8, a, b);
}

pub inline fn strLt(a: []const u8, b: []const u8) bool {
    return strCmp(a, b) < 0;
}

pub inline fn strLe(a: []const u8, b: []const u8) bool {
    return strCmp(a, b) <= 0;
}

pub inline fn strGt(a: []const u8, b: []const u8) bool {
    return strCmp(a, b) > 0;
}

pub inline fn strGe(a: []const u8, b: []const u8) bool {
    return strCmp(a, b) >= 0;
}

pub inline fn strCase(subject: []const u8, label: []const u8) bool {
    return std.mem.eql(u8, subject, label);
}

/// string + string (event scratch).
pub inline fn concat(a: []const u8, b: []const u8) []const u8 {
    return sm().concat(a, b);
}

/// yyGetReal of a string.
pub inline fn strReal(s: []const u8) f32 {
    return Value.fromString(s).toReal();
}

/// yyGetBool of a string.
pub inline fn strTruthy(s: []const u8) bool {
    return Value.fromString(s).toBool();
}

/// real() of a string: parseFloat / parseInt("0x"); unparseable gives 0.
pub inline fn strToReal(s: []const u8) f32 {
    return string.parseReal(s) orelse 0.0;
}

/// string(x) for a real.
pub inline fn realStr(d: f32) []const u8 {
    return sm().fromReal(d);
}

/// A value as a string: strings as is, anything else through string().
pub inline fn asStr(v: Value) []const u8 {
    return sm().fromValue(v);
}

// ---------------------------------------------------------------------------
// Arithmetic
// ---------------------------------------------------------------------------

/// yyfplus on values: string + string concatenates, anything else adds as
/// reals (a string plus a non-string is a runner error that falls through to
/// real addition, Function_Maths.js L1853-1856).
pub fn add(a: Value, b: Value) Value {
    if (a == .string and b == .string) return Value.fromString(concat(a.string, b.string));
    return Value.fromReal(a.toReal() + b.toReal());
}

/// yyfdiv
pub fn div(a: f32, b: f32) f32 {
    const a_nan = std.math.isNan(a);
    const b_nan = std.math.isNan(b);
    if (a_nan or b_nan) {
        if (a_nan and b_nan) return 1.0;
        if (a_nan) return if (std.math.isFinite(b)) a else 1.0;
        return if (std.math.isFinite(a)) b else 1.0;
    }
    if (a == b) return 1.0;
    const ia = math.toInt32(a);
    const ib = math.toInt32(b);
    if (ib == 0) return 0.0; // ~~(x / 0) == 0 after the runner's divide-by-zero error
    const q: f32 = @as(f32, @floatFromInt(ia)) / @as(f32, @floatFromInt(ib));
    return @floatFromInt(math.toInt32(q));
}

/// JS % (fmodf).
pub inline fn mod(a: f32, b: f32) f32 {
    return @rem(a, b);
}

pub inline fn bitand(a: f32, b: f32) f32 {
    return @floatFromInt(math.toInt32(a) & math.toInt32(b));
}

pub inline fn bitor(a: f32, b: f32) f32 {
    return @floatFromInt(math.toInt32(a) | math.toInt32(b));
}

pub inline fn bitxor(a: f32, b: f32) f32 {
    return @floatFromInt(math.toInt32(a) ^ math.toInt32(b));
}

pub inline fn bitnot(a: f32) f32 {
    return @floatFromInt(~math.toInt32(a));
}

/// yyfbitshiftleft/right: the magnitude goes through `new Long(v)` (whose
/// low word is ToInt32(v)), is shifted as a 64-bit value and re-negated.
fn shift(a: f32, n: f32, comptime left: bool) f32 {
    const s = math.toInt32(n);
    const neg = a < 0.0;
    const v: i64 = @as(u32, @bitCast(math.toInt32(if (neg) -a else a)));
    const r: i64 = if (s >= 64) 0 else blk: {
        const k: u6 = @intCast(@as(u32, @bitCast(s)) & 63);
        break :blk if (left) @bitCast(@as(u64, @bitCast(v)) << k) else v >> k;
    };
    const f: f32 = @floatFromInt(r);
    return if (neg) -f else f;
}

pub fn shl(a: f32, n: f32) f32 {
    return shift(a, n, true);
}

pub fn shr(a: f32, n: f32) f32 {
    return shift(a, n, false);
}

// ---------------------------------------------------------------------------
// Instances
// ---------------------------------------------------------------------------

/// Instance as a GML value (its id), noone for null.
pub inline fn id(p: ?*const Instance) f32 {
    return if (p) |inst| @floatFromInt(inst.id) else @floatFromInt(GM_NOONE);
}

/// Object/instance argument as passed to runtime queries.
pub inline fn target(t: f32) i32 {
    return math.toInt32(t);
}

/// yyInst(): the single instance `obj.var` refers to: self for self/all,
/// other, an instance id (even if already marked for destruction), or the
/// object's first own instance, falling back to its first descendant (an
/// abstract parent such as `oCharacter.x`, as GM8/desktop runners do).
pub fn deref(t_real: f32, self: *Instance, other: *Instance) ?*Instance {
    const t = target(t_real);
    if (t == GM_SELF or t == GM_ALL) return self;
    if (t == GM_OTHER) return other;
    const mgr = runtime.InstanceManager.get();
    if (t >= instance.INSTANCE_ID_BASE) {
        runtime.profile.count(.deref_id, 1);
        return mgr.findById(t);
    }
    if (!runtime.ObjectRegistry.get().valid(t)) return null;
    const t0 = runtime.profile.startSection();
    defer runtime.profile.stopSection(.deref_obj, t0);
    var c: instance.InstanceCursor = .{};
    mgr.searchBegin(&c, t);
    var first_child: ?*Instance = null;
    while (mgr.searchNext(&c, t)) |p| {
        if (p.object_index == t) return p;
        if (first_child == null) first_child = p;
    }
    return first_child;
}

// User instance variables: vars[] holds reals, strs[] strings, vals[]
// everything else. The null-tolerant forms serve `target.var`.

pub inline fn ivar(p: ?*const Instance, i: usize) f32 {
    return if (p) |inst| inst.vars[i] else 0.0;
}

pub inline fn ivarSet(p: ?*Instance, i: usize, v: f32) void {
    if (p) |inst| inst.vars[i] = v;
}

pub inline fn svar(p: ?*const Instance, i: usize) []const u8 {
    return if (p) |inst| inst.strs[i] else "";
}

/// Persistent string store: copies `v` into a block owned by the slot.
pub inline fn svarSet(p: ?*Instance, i: usize, v: []const u8) void {
    if (p) |inst| sm().assign(&inst.strs[i], v);
}

pub inline fn vvar(p: ?*const Instance, i: usize) Value {
    return if (p) |inst| inst.vals[i] else Value.UNDEFINED;
}

/// Persistent value store (strings copied, arrays adopted or copied).
pub inline fn vvarSet(p: ?*Instance, i: usize, v: Value) void {
    if (p) |inst| sm().assignValue(&inst.vals[i], v);
}

var vvar_sink: Value = Value.UNDEFINED;

/// Slot for array writes into `p.vals[i]`; a scratch slot for null.
pub fn vvarSlot(p: ?*Instance, i: usize) Slot {
    if (p) |inst| return .persistent(&inst.vals[i]);
    vvar_sink = Value.UNDEFINED;
    return .local(&vvar_sink);
}

// ---------------------------------------------------------------------------
// Arrays
// ---------------------------------------------------------------------------

pub inline fn aget(a: Value, i: f32) Value {
    return value.aget(a, i);
}

pub inline fn aref(slot: Slot, i: f32) Slot {
    return value.aref(slot, i);
}

pub inline fn aset(slot: Slot, i: f32, v: Value) void {
    value.aset(slot, i, v);
}

/// Array literal `[a, b, c]` (a temporary array).
pub inline fn arrayLit(items: []const Value) Value {
    return ArrayManager.get().literal(items);
}

/// Struct accessor `s[$ key]`: structs only come from json_parse, which is
/// pending, so reads yield undefined and writes are dropped (recorded).
pub fn structGet(_: Value, _: Value) Value {
    pendingHit("struct accessor [$");
    return Value.UNDEFINED;
}

pub fn structSet(_: Value, _: Value, _: Value) void {
    pendingHit("struct accessor [$");
}

/// repeat (n): iteration count (yyGetInt32).
pub inline fn repeatCount(n: f32) i32 {
    return math.toInt32(n);
}

// ---------------------------------------------------------------------------
// Lowered built-ins
// ---------------------------------------------------------------------------

pub inline fn isReal(v: Value) f32 {
    return b2r(v == .real);
}

pub inline fn isString(v: Value) f32 {
    return b2r(v == .string);
}

pub inline fn isArray(v: Value) f32 {
    return b2r(v == .array_ref);
}

pub inline fn isUndefined(v: Value) f32 {
    return b2r(v == .undefined);
}

pub inline fn arrayLength(v: Value) f32 {
    return if (v == .array_ref) @floatFromInt(ArrayManager.get().length(v.array_ref)) else 0.0;
}

/// real(): parseFloat for strings (Function_String.js L106).
pub fn toReal(v: Value) f32 {
    return switch (v) {
        .real => |r| r,
        .string => |s| strToReal(s),
        .undefined, .array_ref => 0.0, // runner error
    };
}

/// bool() (Function_String.js L161).
pub inline fn toBool(v: Value) f32 {
    return b2r(v.toBool());
}

/// int64(): the port keeps reals, so this truncates toward zero.
pub inline fn int64(d: f32) f32 {
    return if (std.math.isFinite(d)) @trunc(d) else 0.0;
}

// ---------------------------------------------------------------------------
// Typed ds_map reads: missing keys and invalid maps read as undefined
// converted (0 / "undefined").
// ---------------------------------------------------------------------------

pub fn dsMapFindReal(map: f32, key: []const u8) f32 {
    return runtime.DsManager.get().findValue(target(map), key).toReal();
}

/// The map's storage changes on the next mutation: strings are copied into
/// the event scratch.
pub fn dsMapFindStr(map: f32, key: []const u8) []const u8 {
    const v = runtime.DsManager.get().findValue(target(map), key);
    return if (v == .string) sm().temp(v.string) else asStr(v);
}

/// is_undefined(map[? key])
pub fn dsMapMissing(map: f32, key: []const u8) f32 {
    return b2r(runtime.DsManager.get().findValue(target(map), key) == .undefined);
}

// ---------------------------------------------------------------------------
// Events and scripts
// ---------------------------------------------------------------------------

/// Boxed script trampoline (script_execute with a computed index).
pub const ScriptFn = *const fn (self: *Instance, other: *Instance, args: []const Value) Value;

/// Event handler defined directly on an object. `ev_type` / `number` use the
/// GameMaker event codes (collision events use the other object's index).
pub const EventEntry = struct {
    object_index: i32,
    ev_type: i32,
    number: i32,
    func: EventFn,
};

/// Tables generated for a whole project (gml_game.zig).
pub const Game = struct {
    /// Parent object index per object, or -1.
    object_parents: []const i32,
    /// Sorted by (object_index, ev_type, number).
    events: []const EventEntry,
    /// Boxed trampolines by script index.
    scripts: []const ?ScriptFn,
    /// gml_pragma("global", ...) scripts.
    global_init: ?*const fn () void = null,
};

const max_objects = runtime.object.MAX_OBJECTS;
const alarm_count = runtime.instance.ALARM_COUNT;
const event_stack_max = 64;

const EventFrame = struct {
    object_index: i32,
    ev_type: i32,
    number: i32,
};

// Dispatch cache: the loop asks every instance for its step, alarm and draw
// handlers every frame; most objects define none. Built once at install.
//  - type_mask[o]: bit t set if o or an ancestor defines any event of type t;
//  - dense[o][slot]: inherited handler for step 0-2, alarm 0-11, the eight
//    draw numbers and the Other events the loop polls (outside, boundary,
//    animation end).
const dense_step = 0;
const dense_alarm = dense_step + 3;
const dense_draw = dense_alarm + alarm_count;
const dense_other = dense_draw + 8;
const dense_count = dense_other + other_numbers.len;

const other_numbers = [_]i32{ loop.EV_OTHER_OUTSIDE, loop.EV_OTHER_BOUNDARY, loop.EV_OTHER_ANIMATION_END };

const draw_numbers = [8]i32{
    loop.EV_DRAW_NORMAL,    loop.EV_DRAW_GUI,     loop.EV_DRAW_BEGIN, loop.EV_DRAW_END,
    loop.EV_DRAW_GUI_BEGIN, loop.EV_DRAW_GUI_END, loop.EV_DRAW_PRE,   loop.EV_DRAW_POST,
};

const State = struct {
    game: ?*const Game = null,
    events: [event_stack_max]EventFrame = undefined,
    event_depth: usize = 0,
    /// Pushes beyond event_stack_max (not recorded).
    event_overflow: usize = 0,
    cache_ready: bool = false,
    /// game.events is sorted by (object, type, number): each object's own
    /// handlers are events[own_start[o]..][0..own_len[o]], and own_mask[o]
    /// has bit t set if it defines any event of type t (types >= 32 set all).
    own_ready: bool = false,
    own_start: [max_objects]u16 = undefined,
    own_len: [max_objects]u16 = undefined,
    own_mask: [max_objects]u32 = undefined,
    type_mask: [max_objects]u32 = undefined,
    dense: [max_objects][dense_count]?EventFn = undefined,
    pending: [pending_max][]const u8 = undefined,
    pending_count: usize = 0,
};

const pending_max = 512;

var state: State = .{};

/// Installs the generated tables (borrowed).
pub fn install(game: *const Game) void {
    state.game = game;
    buildDispatchCache();
}

pub fn installedGame() ?*const Game {
    return state.game;
}

/// Runs the installed game's gml_pragma("global") scripts (once, before the
/// first room; assets must already be installed).
pub fn globalInit() void {
    const game = state.game orelse return;
    if (game.global_init) |f| f();
}

/// Hooks the game loop needs from the generated code: event lookup, draw_self
/// and the end-of-tick safe point (string/array recycling).
pub fn loopHooks() loop.LoopHooks {
    return .{
        .find_event = findEvent,
        .find_own_event = findOwnEvent,
        .draw_self = drawSelf,
        .safe_point = safePoint,
    };
}

pub fn roomHooks() room.RoomHooks {
    return .{ .perform = performEvent, .room_begin = roomBegin };
}

fn drawSelf(inst: *Instance) void {
    runtime.DrawManager.get().drawSelf(inst);
}

/// End-of-tick safe point: no generated code is on the stack.
pub fn safePoint() void {
    sm().safePoint();
}

/// Room start runs from the loop (no GML on the stack): also a safe point.
pub fn roomBegin(_: i32) void {
    sm().safePoint();
}

/// Mark returned by `eventPush`, consumed by `eventPop`.
pub const EventMark = StringManager.EventMark;

/// Generated event wrappers bracket their body with push/pop: enters the
/// (self, other) context, records the running handler for event_inherited(),
/// and opens the event's string scratch / temporary array scope.
pub fn eventPush(self: *Instance, other: *Instance, object_index: i32, ev_type: i32, number: i32) EventMark {
    runtime.ContextManager.get().push(self, other);
    if (state.event_depth >= event_stack_max) {
        state.event_overflow += 1;
    } else {
        state.events[state.event_depth] = .{ .object_index = object_index, .ev_type = ev_type, .number = number };
        state.event_depth += 1;
    }
    return sm().eventBegin();
}

pub fn eventPop(mark: EventMark) void {
    sm().eventEnd(mark);
    if (state.event_overflow > 0) {
        state.event_overflow -= 1;
    } else if (state.event_depth > 0) {
        state.event_depth -= 1;
    }
    runtime.ContextManager.get().pop();
}

/// Room and instance creation code wrappers bracket their body with
/// codePush / codePop: the (self, other) context and the string scratch /
/// temporary array scope of an event, but no event frame (as in C, creation
/// code is not an event for event_inherited()).
pub fn codePush(self: *Instance, other: *Instance) EventMark {
    runtime.ContextManager.get().push(self, other);
    return sm().eventBegin();
}

pub fn codePop(mark: EventMark) void {
    sm().eventEnd(mark);
    runtime.ContextManager.get().pop();
}

fn entryOrder(e: EventEntry, object_index: i32, ev_type: i32, number: i32) std.math.Order {
    if (e.object_index != object_index) return std.math.order(e.object_index, object_index);
    if (e.ev_type != ev_type) return std.math.order(e.ev_type, ev_type);
    return std.math.order(e.number, number);
}

/// Handler defined on the object itself (no inheritance), or null.
pub fn findOwnEvent(object_index: i32, ev_type: i32, number: i32) ?EventFn {
    const game = state.game orelse return null;
    var lo: usize = 0;
    var hi: usize = game.events.len;
    if (state.own_ready and object_index >= 0 and object_index < game.object_parents.len) {
        const o: usize = @intCast(object_index);
        if (ev_type >= 0 and ev_type < 32 and state.own_mask[o] & (@as(u32, 1) << @intCast(ev_type)) == 0) return null;
        lo = state.own_start[o];
        hi = lo + state.own_len[o];
    }
    while (lo < hi) {
        const mid = lo + (hi - lo) / 2;
        switch (entryOrder(game.events[mid], object_index, ev_type, number)) {
            .eq => return game.events[mid].func,
            .lt => lo = mid + 1,
            .gt => hi = mid,
        }
    }
    return null;
}

fn parentOf(object_index: i32) i32 {
    const game = state.game orelse return -1;
    if (object_index < 0 or object_index >= game.object_parents.len) return -1;
    return game.object_parents[@intCast(object_index)];
}

fn findEventUncached(object_index: i32, ev_type: i32, number: i32) ?EventFn {
    runtime.profile.count(.find_event_slow, 1);
    var o = object_index;
    var guard: usize = 0;
    while (o >= 0 and guard < max_objects) : (guard += 1) {
        if (findOwnEvent(o, ev_type, number)) |f| return f;
        o = parentOf(o);
    }
    return null;
}

fn denseSlot(ev_type: i32, number: i32) ?usize {
    return switch (ev_type) {
        loop.EV_TYPE_STEP => if (number >= 0 and number < 3) dense_step + @as(usize, @intCast(number)) else null,
        loop.EV_TYPE_ALARM => if (number >= 0 and number < alarm_count) dense_alarm + @as(usize, @intCast(number)) else null,
        loop.EV_TYPE_DRAW => if (number == 0)
            dense_draw
        else if (number >= 72 and number <= 77)
            dense_draw + 2 + @as(usize, @intCast(number - 72))
        else if (number == 64)
            dense_draw + 1
        else
            null,
        loop.EV_TYPE_OTHER => for (other_numbers, 0..) |on, s| {
            if (number == on) break dense_other + s;
        } else null,
        else => null,
    };
}

fn buildDispatchCache() void {
    state.cache_ready = false;
    state.own_ready = false;
    const game = state.game orelse return;
    const n = game.object_parents.len;
    if (n > max_objects) return;
    const own = &state.own_mask;
    @memset(own[0..n], 0);
    @memset(state.own_start[0..n], 0);
    @memset(state.own_len[0..n], 0);
    // The ranges need the sort findOwnEvent's binary search already assumes
    // and indices that fit; otherwise lookups keep searching the whole table.
    var ranges_ok = game.events.len <= std.math.maxInt(u16);
    for (game.events, 0..) |ev, i| {
        if (i > 0 and entryOrder(game.events[i - 1], ev.object_index, ev.ev_type, ev.number) != .lt) ranges_ok = false;
        if (ev.object_index >= 0 and ev.object_index < n) {
            const o: usize = @intCast(ev.object_index);
            // Types beyond the mask width always take the slow path.
            own[o] |= if (ev.ev_type >= 0 and ev.ev_type < 32)
                @as(u32, 1) << @intCast(ev.ev_type)
            else
                0xFFFF_FFFF;
            if (ranges_ok) {
                if (state.own_len[o] == 0) state.own_start[o] = @intCast(i);
                state.own_len[o] += 1;
            }
        }
    }
    state.own_ready = ranges_ok;
    for (0..n) |o| {
        var mask: u32 = 0;
        var p: i32 = @intCast(o);
        var guard: usize = 0;
        while (p >= 0 and p < n and guard < max_objects) : (guard += 1) {
            mask |= own[@intCast(p)];
            p = parentOf(p);
        }
        state.type_mask[o] = mask;
        const oi: i32 = @intCast(o);
        for (0..3) |s| state.dense[o][dense_step + s] = findEventUncached(oi, loop.EV_TYPE_STEP, @intCast(s));
        for (0..alarm_count) |s| state.dense[o][dense_alarm + s] = findEventUncached(oi, loop.EV_TYPE_ALARM, @intCast(s));
        for (draw_numbers, 0..) |dn, s| state.dense[o][dense_draw + s] = findEventUncached(oi, loop.EV_TYPE_DRAW, dn);
        for (other_numbers, 0..) |on, s| state.dense[o][dense_other + s] = findEventUncached(oi, loop.EV_TYPE_OTHER, on);
    }
    state.cache_ready = true;
}

/// Handler of event (type, number) for an object, inherited through the
/// parent chain, or null (LoopHooks.find_event).
pub fn findEvent(object_index: i32, ev_type: i32, number: i32) ?EventFn {
    const game = state.game orelse return null;
    if (!state.cache_ready or object_index < 0 or object_index >= game.object_parents.len) {
        return findEventUncached(object_index, ev_type, number);
    }
    const o: usize = @intCast(object_index);
    if (ev_type >= 0 and ev_type < 32 and state.type_mask[o] & (@as(u32, 1) << @intCast(ev_type)) == 0) return null;
    if (denseSlot(ev_type, number)) |slot| return state.dense[o][slot];
    return findEventUncached(object_index, ev_type, number);
}

/// event_inherited(): runs the nearest ancestor's handler for the current
/// event (no-op at the root or outside events).
pub fn eventInherited(self: *Instance, other: *Instance) void {
    if (state.event_depth == 0 or state.event_overflow > 0) return;
    const cur = state.events[state.event_depth - 1];
    // The parent's PerformEvent is gated too (yyObject.js L702).
    if (runtime.RoomManager.get().eventBlocked(self, cur.ev_type)) return;
    var o = parentOf(cur.object_index);
    var guard: usize = 0;
    while (o >= 0 and guard < max_objects) : (guard += 1) {
        if (findOwnEvent(o, cur.ev_type, cur.number)) |f| {
            f(self, other); // the generated handler pushes its own frame
            return;
        }
        o = parentOf(o);
    }
}

/// Runs the inherited handler on `inst` with self == other == inst
/// (RoomHooks.perform).
pub fn performEvent(inst: *Instance, ev_type: i32, number: i32) void {
    const f = findEvent(inst.object_index, ev_type, number) orelse return;
    if (!runtime.RoomManager.get().eventBlocked(inst, ev_type)) f(inst, inst);
}

/// script_execute(ind, ...) with a non-constant script index.
pub fn scriptExecute(self: *Instance, other: *Instance, script: f32, args: []const Value) Value {
    const index = target(script);
    const game = state.game orelse return invalidScript();
    if (index < 0 or index >= game.scripts.len) return invalidScript();
    const f = game.scripts[@intCast(index)] orelse return invalidScript();
    return f(self, other, args);
}

fn invalidScript() Value {
    pendingHit("script_execute(<invalid script>)");
    return Value.UNDEFINED;
}

// ---------------------------------------------------------------------------
// Pending built-ins: placeholders record that they were reached (distinct
// names, first-use order) so parity work can see what is still missing.
// ---------------------------------------------------------------------------

pub fn pendingHit(name: []const u8) void {
    for (state.pending[0..state.pending_count]) |seen| {
        if (seen.ptr == name.ptr or std.mem.eql(u8, seen, name)) return;
    }
    if (state.pending_count < pending_max) {
        state.pending[state.pending_count] = name;
        state.pending_count += 1;
    }
}

pub fn pendingCount() usize {
    return state.pending_count;
}

pub fn pendingName(index: usize) ?[]const u8 {
    return if (index < state.pending_count) state.pending[index] else null;
}

pub fn pendingReset() void {
    state.pending_count = 0;
}

/// Resets gml glue state (event stack, context stack, pending list, installed
/// game).
pub fn reset() void {
    state.game = null;
    state.event_depth = 0;
    state.event_overflow = 0;
    state.pending_count = 0;
    state.cache_ready = false;
    state.own_ready = false;
    runtime.ContextManager.get().reset();
    runtime.WithStack.get().reset();
}
